import{_ as n,C as r,o as l,c as h,j as d,a as e,E as o,a5 as a}from"./chunks/framework.CyyS6Zdm.js";const f=JSON.parse('{"title":"图片预览","description":"","frontmatter":{},"headers":[],"relativePath":"components/image-viewer.md","filePath":"components/image-viewer.md","lastUpdated":1787173379000}'),g={name:"components/image-viewer.md"},s={id:"图片预览",tabindex:"-1"};function p(b,t,m,u,x,T){const i=r("Badge"),c=r("XhDemo");return l(),h("div",null,[d("h1",s,[t[0]||(t[0]=e("图片预览 ",-1)),o(i,{type:"info",text:"image-viewer"}),t[1]||(t[1]=e()),t[2]||(t[2]=d("a",{class:"header-anchor",href:"#图片预览","aria-label":'Permalink to "图片预览 <Badge type="info" text="image-viewer" />"'},"​",-1))]),t[3]||(t[3]=a('<p>点开看大图：全屏浮层里可以缩放、旋转、翻转与翻页。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>图片细节重要（截图、单据、商品图）。</li><li>一组图需要连续浏览。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>图本身已经足够大：不必再套一层。</li><li>需要的是编辑（裁切、标注）：这是只读的查看器。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li><code>items</code> 给整组图，<code>index</code> 决定当前哪一张，<code>loop</code> 决定是否回绕。</li><li>缩放步长与上下限可调。</li><li>关闭后焦点归还触发器。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>触发器打开全屏看片：滚轮缩放、拖拽平移、工具条给缩放/旋转/翻转/归零，Esc 或点遮罩关闭</p>',10)),o(c,{src:"image-viewer/01-basic"}),t[4]||(t[4]=d("h3",{id:"相册与翻页",tabindex:"-1"},[e("相册与翻页 "),d("a",{class:"header-anchor",href:"#相册与翻页","aria-label":'Permalink to "相册与翻页"'},"​")],-1)),t[5]||(t[5]=d("p",null,"多张图共用一个看片浮层：两侧按钮或方向键翻页、计数报「第几张」，缩放旋转在换图时归零",-1)),o(c,{src:"image-viewer/02-album"}),t[6]||(t[6]=d("h3",{id:"受控与文案",tabindex:"-1"},[e("受控与文案 "),d("a",{class:"header-anchor",href:"#受控与文案","aria-label":'Permalink to "受控与文案"'},"​")],-1)),t[7]||(t[7]=d("p",null,"open 与 index 双受控；translations 换工具条的可及名与计数文案",-1)),o(c,{src:"image-viewer/03-controlled"}),t[8]||(t[8]=a('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-image-viewer&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhImageViewerCloseTrigger</code> <code>XhImageViewerContent</code> <code>XhImageViewerCounter</code> <code>XhImageViewerFlipHorizontalTrigger</code> <code>XhImageViewerFlipVerticalTrigger</code> <code>XhImageViewerImage</code> <code>XhImageViewerNextTrigger</code> <code>XhImageViewerPrevTrigger</code> <code>XhImageViewerResetTrigger</code> <code>XhImageViewerRoot</code> <code>XhImageViewerRotateLeftTrigger</code> <code>XhImageViewerRotateRightTrigger</code> <code>XhImageViewerToolbar</code> <code>XhImageViewerTrigger</code> <code>XhImageViewerViewport</code> <code>XhImageViewerZoomInTrigger</code> <code>XhImageViewerZoomOutTrigger</code></td></tr><tr><td>组合式函数</td><td><code>useImageViewer</code></td></tr><tr><td>状态机</td><td><code>imageViewerMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/image-viewer.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;image-viewer&quot;</code>：<code>trigger</code> · <code>backdrop</code> · <code>positioner</code> · <strong><code>content</code></strong> · <code>viewport</code> · <strong><code>image</code></strong> · <code>toolbar</code> · <code>zoom-in-trigger</code> · <code>zoom-out-trigger</code> · <code>rotate-left-trigger</code> · <code>rotate-right-trigger</code> · <code>flip-horizontal-trigger</code> · <code>flip-vertical-trigger</code> · <code>reset-trigger</code> · <code>prev-trigger</code> · <code>next-trigger</code> · <code>counter</code> · <code>close-trigger</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>items</code></td><td><code>ImageViewerItem[]</code></td><td></td><td>图片清单。看单张就给长度 1 的数组。缺省为空，此时打开也只有工具条与空视口。</td></tr><tr><td><code>open</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>defaultOpen</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>index</code></td><td><code>number</code></td><td></td><td>当前下标（0 起）。给定即受控：内部不再自改，只发 onIndexChange。</td></tr><tr><td><code>defaultIndex</code></td><td><code>number</code></td><td></td><td>非受控初值，默认 0。</td></tr><tr><td><code>loop</code></td><td><code>boolean</code></td><td></td><td>前后翻页到头是否回绕，默认 true。</td></tr><tr><td><code>zoomStep</code></td><td><code>number</code></td><td></td><td>缩放步长（加法），默认 0.5。</td></tr><tr><td><code>minScale</code></td><td><code>number</code></td><td></td><td>缩放下限，默认 0.25。</td></tr><tr><td><code>maxScale</code></td><td><code>number</code></td><td></td><td>缩放上限，默认 8。</td></tr><tr><td><code>closeOnEscape</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>closeOnInteractOutside</code></td><td><code>boolean</code></td><td></td><td>点遮罩（内容之外）关闭，默认 true。</td></tr><tr><td><code>restoreFocus</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;ImageViewerTranslations&gt;</code></td><td></td><td></td></tr><tr><td><code>onOpenChange</code></td><td><code>(details: ImageViewerOpenChangeDetails) =&gt; void</code></td><td></td><td>open 变化意图回调；受控时是唯一出口，非受控时随内部转移一并通知。</td></tr><tr><td><code>onIndexChange</code></td><td><code>(details: ImageViewerIndexChangeDetails) =&gt; void</code></td><td></td><td>下标变化意图回调；受控时是唯一出口，非受控随内部写入一并通知。</td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>open-change</code></td><td><code>ImageViewerOpenChangeDetails</code></td><td>open 状态变化；detail 为 <code>{ open: boolean }</code></td></tr><tr><td><code>index-change</code></td><td><code>ImageViewerIndexChangeDetails</code></td><td>下标变化；detail 为 <code>{ index: number }</code></td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhImageViewerRoot</code></td><td><code>default</code></td><td><code>ImageViewerRootSlotProps</code></td><td></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>对外可见的状态落在 <code>data-state</code> 上，写样式与断言都读它：</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>trigger</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>backdrop</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>positioner</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>content</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>viewport</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>image</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>toolbar</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>counter</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr></tbody></table><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>open</code> · <code>closed</code></p><p><strong>事件</strong>：<code>OPEN</code> · <code>CLOSE</code> · <code>INDEX.SET</code> · <code>INDEX.NEXT</code> · <code>INDEX.PREV</code> · <code>ZOOM.BY</code> · <code>ZOOM.SET</code> · <code>ROTATE.BY</code> · <code>FLIP</code> · <code>TRANSFORM.RESET</code> · <code>PAN.MOVE</code> · <code>PAN.START</code> · <code>PAN.END</code> · <code>CONTROLLED.OPEN</code> · <code>CONTROLLED.CLOSE</code></p><p><strong>判据</strong>：<code>isOpenControlled</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useImageViewer</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>open</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>index</code></td><td><code>number</code></td><td>当前下标，恒在 [0, count - 1] 内；清单为空时为 0。</td></tr><tr><td><code>count</code></td><td><code>number</code></td><td></td></tr><tr><td><code>currentItem</code></td><td><code>ImageViewerItem | null</code></td><td>当前那张图；清单为空时为 null。</td></tr><tr><td><code>transform</code></td><td><code>ImageViewerTransform</code></td><td></td></tr><tr><td><code>panning</code></td><td><code>boolean</code></td><td>正在拖拽平移。</td></tr><tr><td><code>canPrev</code></td><td><code>boolean</code></td><td>往前还翻得动（loop 且多于一张时恒为 true）。</td></tr><tr><td><code>canNext</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>setOpen</code></td><td><code>(next: boolean) =&gt; void</code></td><td></td></tr><tr><td><code>setIndex</code></td><td><code>(next: number) =&gt; void</code></td><td>直接跳到某一张；越界会被夹回 [0, count - 1]。换图变换归零。</td></tr><tr><td><code>next</code></td><td><code>() =&gt; void</code></td><td></td></tr><tr><td><code>prev</code></td><td><code>() =&gt; void</code></td><td></td></tr><tr><td><code>zoomIn</code></td><td><code>() =&gt; void</code></td><td></td></tr><tr><td><code>zoomOut</code></td><td><code>() =&gt; void</code></td><td></td></tr><tr><td><code>setScale</code></td><td><code>(scale: number) =&gt; void</code></td><td></td></tr><tr><td><code>rotateLeft</code></td><td><code>() =&gt; void</code></td><td></td></tr><tr><td><code>rotateRight</code></td><td><code>() =&gt; void</code></td><td></td></tr><tr><td><code>flipHorizontal</code></td><td><code>() =&gt; void</code></td><td></td></tr><tr><td><code>flipVertical</code></td><td><code>() =&gt; void</code></td><td></td></tr><tr><td><code>reset</code></td><td><code>() =&gt; void</code></td><td>变换整体归零（缩放/旋转/翻转/平移）。</td></tr><tr><td><code>getTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getBackdropProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getPositionerProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getContentProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getViewportProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getImageProps</code></td><td><code>() =&gt; T[&#39;img&#39;]</code></td><td></td></tr><tr><td><code>getToolbarProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getZoomInTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getZoomOutTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getRotateLeftTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getRotateRightTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getFlipHorizontalTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getFlipVerticalTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getResetTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getPrevTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getNextTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getCounterProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getCloseTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/dialog-modal/#keyboardinteraction" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Enter</code> / <code>Space</code></td><td>focus in trigger</td><td>打开看片浮层并把焦点移入 content</td></tr><tr><td><code>Escape</code></td><td>open</td><td>关闭并把焦点还给 trigger（closeOnEscape=false 时不关）</td></tr><tr><td><code>Tab</code></td><td>open</td><td>在 content 内向后循环焦点</td></tr><tr><td><code>Shift+Tab</code></td><td>open</td><td>在 content 内向前循环焦点</td></tr><tr><td><code>ArrowLeft</code></td><td>open</td><td>上一张</td></tr><tr><td><code>ArrowRight</code></td><td>open</td><td>下一张</td></tr><tr><td><code>Home</code></td><td>open</td><td>跳到第一张</td></tr><tr><td><code>End</code></td><td>open</td><td>跳到最后一张</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>trigger</code></td><td><code>aria-expanded</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>trigger</code></td><td><code>aria-haspopup</code></td><td>&#39;dialog&#39;</td></tr><tr><td><code>backdrop</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>content</code></td><td><code>aria-label</code></td><td>currentItem?.alt</td></tr><tr><td><code>content</code></td><td><code>aria-modal</code></td><td>&#39;true&#39;</td></tr><tr><td><code>content</code></td><td><code>role</code></td><td>&#39;dialog&#39;</td></tr><tr><td><code>toolbar</code></td><td><code>aria-label</code></td><td>label.content</td></tr><tr><td><code>toolbar</code></td><td><code>role</code></td><td>&#39;toolbar&#39;</td></tr><tr><td><code>counter</code></td><td><code>aria-live</code></td><td>&#39;polite&#39;</td></tr></tbody></table><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/image-viewer.css</code> 按部件选择：<code>[data-scope=&quot;image-viewer&quot;][data-part=&quot;trigger&quot;]</code>。它落在 <code>xihan.components</code> 与 <code>xihan.motion</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>trigger</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>backdrop</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>positioner</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>content</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>viewport</code></td><td><code>data-panning</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>viewport</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>image</code></td><td><code>data-panning</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>image</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>toolbar</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>counter</code></td><td><code>data-count</code></td><td>String(count)</td></tr><tr><td><code>counter</code></td><td><code>data-index</code></td><td>String(index + 1)</td></tr><tr><td><code>counter</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-image-viewer-backdrop-bg</code> · <code>--xh-image-viewer-chrome-bg</code> · <code>--xh-image-viewer-fg</code></p><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p>关键帧 <code>xh-fade-in</code> · <code>xh-fade-out</code> 随皮肤自带，不引用别处文件里的名字；状态切换走 <code>transition</code>。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p><code>prefers-reduced-motion: reduce</code> 下本组件另有降级规则。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>触发器用<a href="./image">图片</a>；一组<a href="./image">图片</a>共用一个预览层。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>显示&quot;第几张 / 共几张&quot;，用户才知道还有多少。</li><li>工具栏按钮全部给可及名字：它们只有图标。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>打开后 Escape 关不掉。</li><li>缩放后没有复位入口。</li></ul>',48))])}const w=n(g,[["render",p]]);export{f as __pageData,w as default};
